use prism::call_graph::{CallGraph, CallSite, FunctionId};
use prism::navigation::NavigationIndex;
use prism::resolution::{ResolutionConfidence, ResolutionKind};
use prism::repo_loader::load_repo;
use serde_json::json;
use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};

fn dir_of(path: &str) -> &str {
    path.rsplit_once('/').map(|(d, _)| d).unwrap_or("")
}

fn file_stem(path: &str) -> &str {
    let name = path.rsplit('/').next().unwrap_or(path);
    name.rsplit_once('.').map(|(s, _)| s).unwrap_or(name)
}

fn is_static(cg: &CallGraph, fid: &FunctionId, name: &str) -> bool {
    cg.static_functions
        .contains(&(fid.file.clone(), name.to_string()))
}

fn free_nonstatic_candidates<'a>(cg: &'a CallGraph, name: &str) -> Vec<&'a FunctionId> {
    cg.functions
        .get(name)
        .into_iter()
        .flat_map(|ids| ids.iter())
        .filter(|fid| !cg.method_owners.contains_key(*fid))
        .filter(|fid| !is_static(cg, fid, name))
        .collect()
}

fn current_r3_like_module_match(module_path: &str, fid: &FunctionId) -> bool {
    let module_last = module_path.rsplit('/').next().unwrap_or(module_path);
    let module_stem = module_last.rsplit('.').next_back().unwrap_or(module_last);
    let stem_hit = file_stem(&fid.file) == module_stem;
    let dir_hit = fid
        .file
        .rsplit('/')
        .nth(1)
        .map(|d| d == module_last)
        .unwrap_or(false);
    stem_hit || dir_hit
}

fn normalize_rel(path: &str) -> String {
    let mut parts = Vec::new();
    for part in path.split('/') {
        match part {
            "" | "." => {}
            ".." => {
                parts.pop();
            }
            p => parts.push(p),
        }
    }
    parts.join("/")
}

fn resolved_relative_module_dirs(site: &CallSite, module_path: &str) -> BTreeSet<String> {
    let mut dirs = BTreeSet::new();
    if !(module_path.starts_with("./") || module_path.starts_with("../")) {
        return dirs;
    }
    let base = dir_of(&site.caller.file);
    let joined = if base.is_empty() {
        module_path.to_string()
    } else {
        format!("{base}/{module_path}")
    };
    let normalized = normalize_rel(&joined);
    dirs.insert(normalized.clone());
    if let Some((d, _)) = normalized.rsplit_once('/') {
        dirs.insert(d.to_string());
    }
    dirs
}

fn relative_module_match(site: &CallSite, module_path: &str, fid: &FunctionId) -> bool {
    if !(module_path.starts_with("./") || module_path.starts_with("../")) {
        return false;
    }
    let base = dir_of(&site.caller.file);
    let joined = if base.is_empty() {
        module_path.to_string()
    } else {
        format!("{base}/{module_path}")
    };
    let normalized = normalize_rel(&joined);
    let no_ext = fid
        .file
        .rsplit_once('.')
        .map(|(s, _)| s)
        .unwrap_or(fid.file.as_str());
    fid.file == format!("{normalized}.js")
        || fid.file == format!("{normalized}.ts")
        || fid.file == format!("{normalized}.tsx")
        || fid.file == format!("{normalized}/index.js")
        || fid.file == format!("{normalized}/index.ts")
        || fid.file == format!("{normalized}/index.tsx")
        || no_ext == normalized
}

#[derive(Default)]
struct Counts {
    sites: usize,
    edges: usize,
    same_file_sites: usize,
    same_file_edges: usize,
    same_dir_single_sites: usize,
    same_dir_single_edges: usize,
    same_dir_multi_sites: usize,
    same_dir_multi_edges: usize,
    import_alias_sites: usize,
    import_alias_edges: usize,
    import_alias_single_sites: usize,
    import_alias_single_edges: usize,
    import_alias_multi_sites: usize,
    import_alias_multi_edges: usize,
    import_alias_external_sites: usize,
    relative_import_alias_sites: usize,
    relative_import_alias_single_sites: usize,
    relative_import_alias_multi_sites: usize,
    relative_import_alias_external_sites: usize,
    cross_module_sites: usize,
    cross_module_edges: usize,
}

fn bump_site_edges(site_counter: &mut usize, edge_counter: &mut usize, edge_count: usize) {
    *site_counter += 1;
    *edge_counter += edge_count;
}

fn classify(cg: &CallGraph, site: &CallSite, resolved: &[&FunctionId], counts: &mut Counts) {
    let edge_count = resolved.len();
    counts.sites += 1;
    counts.edges += edge_count;

    let same_file: Vec<_> = resolved
        .iter()
        .copied()
        .filter(|fid| fid.file == site.caller.file)
        .collect();
    if !same_file.is_empty() {
        bump_site_edges(
            &mut counts.same_file_sites,
            &mut counts.same_file_edges,
            same_file.len(),
        );
        return;
    }

    let caller_dir = dir_of(&site.caller.file);
    let same_dir: Vec<_> = resolved
        .iter()
        .copied()
        .filter(|fid| dir_of(&fid.file) == caller_dir)
        .collect();
    match same_dir.len() {
        0 => {}
        1 => {
            bump_site_edges(
                &mut counts.same_dir_single_sites,
                &mut counts.same_dir_single_edges,
                1,
            );
            return;
        }
        n => {
            bump_site_edges(
                &mut counts.same_dir_multi_sites,
                &mut counts.same_dir_multi_edges,
                n,
            );
            return;
        }
    }

    if let Some(module_path) = cg
        .imports
        .get(&site.caller.file)
        .and_then(|m| m.get(&site.callee_name))
    {
        counts.import_alias_sites += 1;
        counts.import_alias_edges += edge_count;

        let all_free = free_nonstatic_candidates(cg, &site.callee_name);
        let mut matched: Vec<&FunctionId> = all_free
            .iter()
            .copied()
            .filter(|fid| current_r3_like_module_match(module_path, fid))
            .collect();

        if module_path.starts_with("./") || module_path.starts_with("../") {
            let relative_matched: Vec<&FunctionId> = all_free
                .iter()
                .copied()
                .filter(|fid| relative_module_match(site, module_path, fid))
                .collect();
            if !relative_matched.is_empty() {
                matched = relative_matched;
            }
            counts.relative_import_alias_sites += 1;
        }

        match matched.len() {
            0 => {
                counts.import_alias_external_sites += 1;
                if module_path.starts_with("./") || module_path.starts_with("../") {
                    counts.relative_import_alias_external_sites += 1;
                }
                return;
            }
            1 => {
                counts.import_alias_single_sites += 1;
                counts.import_alias_single_edges += 1;
                if module_path.starts_with("./") || module_path.starts_with("../") {
                    counts.relative_import_alias_single_sites += 1;
                }
                return;
            }
            n => {
                counts.import_alias_multi_sites += 1;
                counts.import_alias_multi_edges += n;
                if module_path.starts_with("./") || module_path.starts_with("../") {
                    counts.relative_import_alias_multi_sites += 1;
                }
                return;
            }
        }
    }

    counts.cross_module_sites += 1;
    counts.cross_module_edges += edge_count;
}

fn analyze(repo: &Path) -> anyhow::Result<serde_json::Value> {
    let loaded = load_repo(repo)?;
    let index = NavigationIndex::build(&loaded);
    let cg = &index.cpg.call_graph;
    let mut by_ext: BTreeMap<String, Counts> = BTreeMap::new();
    let mut samples: BTreeMap<String, Vec<serde_json::Value>> = BTreeMap::new();

    for sites in cg.calls.values() {
        for site in sites {
            let outcome = cg.resolve_call_site_full(site);
            let free_multi: Vec<&FunctionId> = outcome
                .resolved
                .iter()
                .filter(|r| {
                    r.kind == ResolutionKind::FreeMulti
                        && r.confidence == ResolutionConfidence::NameOnly
                })
                .map(|r| r.target)
                .collect();
            if free_multi.is_empty() {
                continue;
            }
            let ext = site
                .caller
                .file
                .rsplit_once('.')
                .map(|(_, e)| e.to_string())
                .unwrap_or_default();
            let counts = by_ext.entry(ext.clone()).or_default();
            let before = (
                counts.same_dir_single_sites,
                counts.same_dir_multi_sites,
                counts.import_alias_sites,
                counts.cross_module_sites,
            );
            classify(cg, site, &free_multi, counts);
            let after = (
                counts.same_dir_single_sites,
                counts.same_dir_multi_sites,
                counts.import_alias_sites,
                counts.cross_module_sites,
            );
            if before != after {
                let bucket = if after.0 > before.0 {
                    "same_dir_single"
                } else if after.1 > before.1 {
                    "same_dir_multi"
                } else if after.2 > before.2 {
                    "import_alias"
                } else {
                    "cross_module"
                };
                let entry = samples.entry(format!("{ext}:{bucket}")).or_default();
                if entry.len() < 5 {
                    let import = cg
                        .imports
                        .get(&site.caller.file)
                        .and_then(|m| m.get(&site.callee_name))
                        .cloned();
                    let dirs = import
                        .as_deref()
                        .map(|m| {
                            resolved_relative_module_dirs(site, m)
                                .into_iter()
                                .collect::<Vec<_>>()
                        })
                        .unwrap_or_default();
                    entry.push(json!({
                        "caller": format!("{}:{}:{}-{}", site.caller.file, site.line, site.start_byte, site.end_byte),
                        "callee": site.callee_name,
                        "fanout": free_multi.len(),
                        "import": import,
                        "relative_dirs": dirs,
                        "targets": free_multi.iter().take(8).map(|f| format!("{}:{}", f.file, f.start_line)).collect::<Vec<_>>()
                    }));
                }
            }
        }
    }

    let to_json = |c: &Counts| {
        json!({
            "sites": c.sites,
            "edges": c.edges,
            "same_file": {"sites": c.same_file_sites, "edges": c.same_file_edges},
            "same_dir_single": {"sites": c.same_dir_single_sites, "edges": c.same_dir_single_edges},
            "same_dir_multi": {"sites": c.same_dir_multi_sites, "edges": c.same_dir_multi_edges},
            "import_alias": {
                "sites": c.import_alias_sites,
                "edges": c.import_alias_edges,
                "single": {"sites": c.import_alias_single_sites, "edges": c.import_alias_single_edges},
                "multi": {"sites": c.import_alias_multi_sites, "edges": c.import_alias_multi_edges},
                "external_sites": c.import_alias_external_sites,
                "relative_sites": c.relative_import_alias_sites,
                "relative_single_sites": c.relative_import_alias_single_sites,
                "relative_multi_sites": c.relative_import_alias_multi_sites,
                "relative_external_sites": c.relative_import_alias_external_sites
            },
            "cross_module_residue": {"sites": c.cross_module_sites, "edges": c.cross_module_edges}
        })
    };

    let mut totals = Counts::default();
    for c in by_ext.values() {
        totals.sites += c.sites;
        totals.edges += c.edges;
        totals.same_file_sites += c.same_file_sites;
        totals.same_file_edges += c.same_file_edges;
        totals.same_dir_single_sites += c.same_dir_single_sites;
        totals.same_dir_single_edges += c.same_dir_single_edges;
        totals.same_dir_multi_sites += c.same_dir_multi_sites;
        totals.same_dir_multi_edges += c.same_dir_multi_edges;
        totals.import_alias_sites += c.import_alias_sites;
        totals.import_alias_edges += c.import_alias_edges;
        totals.import_alias_single_sites += c.import_alias_single_sites;
        totals.import_alias_single_edges += c.import_alias_single_edges;
        totals.import_alias_multi_sites += c.import_alias_multi_sites;
        totals.import_alias_multi_edges += c.import_alias_multi_edges;
        totals.import_alias_external_sites += c.import_alias_external_sites;
        totals.relative_import_alias_sites += c.relative_import_alias_sites;
        totals.relative_import_alias_single_sites += c.relative_import_alias_single_sites;
        totals.relative_import_alias_multi_sites += c.relative_import_alias_multi_sites;
        totals.relative_import_alias_external_sites += c.relative_import_alias_external_sites;
        totals.cross_module_sites += c.cross_module_sites;
        totals.cross_module_edges += c.cross_module_edges;
    }

    Ok(json!({
        "repo": repo.display().to_string(),
        "loaded_files": loaded.files.len(),
        "skipped_files": loaded.skipped.len(),
        "total": to_json(&totals),
        "by_extension": by_ext.into_iter().map(|(k, v)| (k, to_json(&v))).collect::<BTreeMap<_, _>>(),
        "samples": samples
    }))
}

fn main() -> anyhow::Result<()> {
    let repos: Vec<PathBuf> = std::env::args_os().skip(1).map(PathBuf::from).collect();
    let values = prism::build_pool::build_pool().install(|| {
        repos
            .iter()
            .map(|repo| analyze(repo))
            .collect::<anyhow::Result<Vec<_>>>()
    })?;
    println!("{}", serde_json::to_string_pretty(&values)?);
    Ok(())
}

